import{z as s,x as i,o as E,c as B,q as t,j as n,D as e,d as A,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"正则化与市场数据","description":"","frontmatter":{"title":"正则化与市场数据","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/slm-regularization-market-data.md","filePath":"quant/slm-regularization-market-data.md","lastUpdated":1791063341000}'),d={name:"quant/slm-regularization-market-data.md"};function m(p,a,S,h,c,u){const r=i("Mermaid");return E(),B("div",null,[a[2]||(a[2]=t('<h1 id="正则化与市场数据" tabindex="-1">正则化与市场数据 <a class="header-anchor" href="#正则化与市场数据" aria-label="Permalink to &quot;正则化与市场数据&quot;">​</a></h1><div class="epigraph"><p>在共线的高维截面里，「无偏」是一个没有意义的词；先收缩，才轮得到谈解释。</p><footer>—— 据 Hoerl and Kennard, *Technometrics*, 1970；Tibshirani, *JRSS-B*, 1996 整理</footer></div><p><a href="/quant/slm-supervised-landscape">上一课</a>把版图钉在信噪比千分位与截面排序评估上，容量于是成为稀缺品。本课从容量最低的一端写起：线性模型配上正则化。它不是入门玩具，而是后面树与网络都必须在协议内打败的基线，也是理解一切「收缩」手段——早停、权重衰减、SDF 正则——的原型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>市场截面的设计矩阵病态：动量族、规模族、流动性族内部高度共线，特征动辄上百个，与有效样本同量级。OLS 在病态设计下方差爆炸——\\(X^\\top X\\) 接近奇异时，\\(\\hat\\beta\\) 的方向由噪声主导，样本内拟合漂亮、样本外翻车。不这么做会错在哪：把上百个原始特征直接塞进回归，得到一份每个系数都「显著」的样本内报告，实盘第一周就开始付方差的钱。缺口是把上一课「省容量」的口号落成可估计的模型：用一份可控的偏差，换掉一大块方差。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条主线。岭回归解 \\((X^\\top X+\\lambda I)\\beta=X^\\top y\\)，对所有系数均匀收缩，共线下方向稳定。LASSO 解 \\(\\min_\\beta\\lVert y-X\\beta\\rVert_2^2+\\lambda\\lVert\\beta\\rVert_1\\)，把弱系数直接压到零，输出稀疏解；elastic net 在两者之间插值，兼顾共线下的稳定与稀疏的选择。三条使用纪律：特征先按日截面 rank、惩罚前标准化（rank 的理由见<a href="/quant/cs-rank-features">特征：滞后、截面 rank</a>）；\\(\\lambda\\) 只能在嵌套验证的内层选，外层折不参与网格（<a href="/quant/nested-cv">嵌套交叉验证</a>）；LASSO 选中的变量集合在共线下不稳定，读作「一个等价代表」，不读作「经济学答案」。定价侧的同型思想是对随机贴现因子做正则（Kozak-Nagel-Santosh），组合侧对协方差与精度矩阵收缩（<a href="/quant/glasso">图形 Lasso 精度矩阵</a>）。</p>',7)),(E(),n(o,null,{default:e(()=>[l(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%85%B1%E7%BA%BF%E7%9A%84%E6%88%AA%E9%9D%A2%E7%89%B9%E5%BE%81%22%5D%20--%3E%20S%5B%22%E6%8C%89%E6%97%A5%20rank%20%E4%B8%8E%E6%A0%87%E5%87%86%E5%8C%96%22%5D%0A%20%20S%20--%3E%20R%5B%22%E5%B2%AD%EF%BC%9A%E5%9D%87%E5%8C%80%E6%94%B6%E7%BC%A9%22%5D%0A%20%20S%20--%3E%20L%5B%22LASSO%20%2F%20%E5%BC%B9%E6%80%A7%E7%BD%91%EF%BC%9A%E7%A8%80%E7%96%8F%E9%80%89%E6%8B%A9%22%5D%0A%20%20R%20--%3E%20V%5B%22%CE%BB%20%E5%9C%A8%E5%86%85%E5%B1%82%E9%AA%8C%E8%AF%81%E9%80%89%22%5D%0A%20%20L%20--%3E%20V%0A%20%20V%20--%3E%20O%5B%22%E5%A4%96%E5%B1%82%E6%B5%8B%E8%AF%95%E6%8A%98%EF%BC%9A%E5%8F%AA%E7%A2%B0%E4%B8%80%E6%AC%A1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正则化的统计本质是控制有效自由度：\\(\\lambda\\) 连续地扣掉模型的容量，偏差方差交易在低信噪比下几乎总是划算，因为压掉的方差远大于引入的偏差。岭在共线下把权重摊到相关簇上，稳定但单系数不可解释；LASSO 在强共线下的选择近乎随机——同一个真实关系，换一年数据，被选中的代表就换了人。这解释了为什么第 7 课的重要性能读法必须换成置换框架而不是看系数。稀疏本身也不是目的：Chinco-Clark-Joseph 用 LASSO 在一分钟收益里只保留少数滞后项，稀疏的价值在于样本外稳定与可维护，不在于「找到了真信号」。</p><p><span class="marginnote">Chinco, Clark-Joseph and Ye, <em>Sparse Signals in the Cross-Section of Returns</em>, <em>Journal of Finance</em>, 2019：高频截面用 LASSO 从数百个滞后收益里挑出极少数，样本外仍显著——稀疏在高维共线下的第一个用途是筛掉噪声，第二个才是选变量。</span></p><p><span class="marginnote">惩罚前必须标准化，否则 λ 的惩罚力度被量纲扭曲：若「市值」以 \\(10^{11}\\) 元计而「换手率」以 \\(0.01\\) 计，同一个 \\(\\lambda\\) 对市值的惩罚近似为零、对换手率近乎清零。按日截面 rank 或 z-score 之后，\\(\\lambda\\) 才对所有系数一视同仁。</span></p><p><span class="marginnote">岭回归可以想象成给每个系数系一根橡皮筋：数据把系数拉向最小二乘解，\\(\\lambda\\) 的橡皮筋往零拉。数据信号越弱（市场数据几乎总是如此），平衡点离零越近——这是「用一点偏差换掉一大块方差」的物理图像。</span></p>',5)),(E(),n(o,null,{default:e(()=>[l(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20C%5B%22%E9%AB%98%E5%BA%A6%E7%9B%B8%E5%85%B3%E7%9A%84%E7%89%B9%E5%BE%81%E7%B0%87%EF%BC%9A%E4%B8%89%E4%B8%AA%E9%83%BD%E7%9C%9F%22%5D%20--%3E%20R%5B%22%E5%B2%AD%EF%BC%9A%E6%9D%83%E9%87%8D%E6%91%8A%E5%88%B0%E7%B0%87%E5%86%85%E6%AF%8F%E4%B8%AA%E6%88%90%E5%91%98%22%5D%0A%20%20C%20--%3E%20L%5B%22LASSO%EF%BC%9A%E5%8F%AA%E7%95%99%E4%B8%80%E4%B8%AA%E3%80%81%E5%85%B6%E4%BD%99%E5%8E%8B%E9%9B%B6%22%5D%0A%20%20R%20--%3E%20RS%5B%22%E8%A7%A3%E7%A8%B3%E5%AE%9A%EF%BC%9A%E6%8D%A2%E6%A0%B7%E6%9C%AC%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%98%22%5D%0A%20%20L%20--%3E%20LS%5B%22%E9%80%89%E6%8B%A9%E4%B8%8D%E7%A8%B3%EF%BC%9A%E6%8D%A2%E4%B8%80%E5%B9%B4%E6%95%B0%E6%8D%AE%E4%BB%A3%E8%A1%A8%E6%8D%A2%E4%BA%BA%22%5D%0A%20%20RS%20--%3E%20P%5B%22%E8%AF%BB%E6%B3%95%EF%BC%9A%E6%8C%89%E7%B0%87%E8%A7%A3%E9%87%8A%EF%BC%8C%E7%94%A8%E7%BD%AE%E6%8D%A2%E8%AF%84%E4%BC%B0%E9%87%8D%E8%A6%81%E6%80%A7%22%5D%0A%20%20LS%20--%3E%20P%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>正则化不修非平稳：对十年数据最优的 \\(\\lambda\\) 对下一年未必；每条 \\(\\lambda\\) 路径上的尝试都计入 \\(N\\) 台账（<a href="/quant/fml-model-selection-protocol">模型选择协议</a>），「调参不算试验」是台账最常见的漏记。收缩后的系数不能直接读作弹性或溢价，截面联立下的解释另有计量口径，本课程不承担。</p><p><span class="marginnote">初学者容易以为 LASSO 选中的变量就是「最重要的那个」；在一簇高度相关的变量里，它近似随机挑了一个代表——被压到零的同伴不是没信息，只是和代表说了同样的话。删掉变量集合要按簇看，不要按名字看。</span> 最后立一条基线规则：后面任何非线性模型，必须在同一协议、同一特征、同一评估下赢过本课的正则化线性，才有升级的理由——GKX 的协议里这个差距常常只有千分位，赢不了它的复杂模型先怀疑自己。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共线加高维使 OLS 方差爆炸；正则化用可控偏差换掉不可控方差。</li><li>岭稳方向、LASSO 给稀疏、弹性网居中；共线下的变量选择是随机代表，不是因果。</li><li>\\(\\lambda\\) 只在内层选，外层折不参与；每次调参计入 \\(N\\) 台账。</li><li>同型思想延伸到 SDF 正则与协方差收缩，本课是后两课一切模型的必败基线。</li><li>出处：Hoerl and Kennard, <em>Technometrics</em>, 1970；Tibshirani, <em>JRSS-B</em>, 1996；Kozak, Nagel and Santosh, <em>Shrinking the Cross-Section</em>, <em>JF</em>, 2020；Gu, Kelly and Xiu, <em>RFS</em>, 2020。</li></ul>',5))])}const D=s(d,[["render",m]]);export{C as __pageData,D as default};
